//! Differential test for `pickup::bonus_kind` (0x29edc, the reward for wiping out an enemy group) against tests/vectors/bonus_vectors.txt,
//! generated by running the original routine (tools/re/gen_bonus_vectors.py).
use mars_rising::pickup::bonus_kind;

#[test]
fn group_bonus_matches_original_executable() {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/vectors/bonus_vectors.txt")).expect("vectors");
    let mut n = 0;
    for (ln, line) in text.lines().enumerate() {
        if line.starts_with('#') || line.trim().is_empty() { continue; }
        let (lhs, rhs) = line.split_once(" -> ").unwrap();
        let t: Vec<&str> = lhs.split(' ').collect();
        let owner: u8 = t[0].parse().unwrap();
        let mut wipes = [t[1].parse::<i32>().unwrap(), t[2].parse::<i32>().unwrap()];
        let raw: u32 = t[3].parse().unwrap();
        let mut log: Vec<String> = vec![];
        let kind = bonus_kind(owner, &mut wipes, |lo, hi| {
            let v = lo + (raw % ((hi - lo + 1) as u32)) as i32;
            log.push(format!("rnd_{}_{}_{}", lo, hi, v));
            v
        });
        log.push(format!("spawn_{}_1_1_1_{}_{}", kind, t[4], t[5]));
        let got = format!("{} {} {}", wipes[0], wipes[1], log.join(","));
        assert_eq!(got, rhs, "line {}", ln + 1);
        n += 1;
    }
    assert!(n >= 600);
}
